 const eight=await http(`/api/admin/orders/${report.cases['08'].orderId}`,undefined,'employee');report.cases['08'].employeeDetail=eight;const cards=eight.data.order.order_items[0].dedications;check('08: exact independent per-unit messages through employee API',cards.length===2&&cards[0].message===dedication('unidad uno').message&&cards[1].message===dedication('unidad dos').message);
 for(const [id,slot] of [['03','qr_1'],['04','qr_2']]){const p=getPayments(report.cases[id].orderId)[0];report.cases[id].paymentSnapshot=p;check(id+': stable QR identity snapshot',p.qr_slot===slot,{payment:p});}
 for(const route of ['/api/admin/system-settings','/api/admin/users'])check('employee denied '+route,(await http(route,undefined,'employee')).status===403);
 check('employee cannot create promotion',(await http('/api/admin/promotions',{name:'DENIED LOCAL',promotion_type:'producto',discount_type:'porcentaje',discount_value:10},'employee')).status===403);
 check('employee cannot issue refunds',(await http(`/api/admin/orders/${report.cases['28'].orderId}/returns`,{type:'reintegro',amount:1,reason:'DENIED LOCAL',idempotency_key:randomUUID()},'employee')).status===403);
 const args={p_customer_phone:report.cases['01'].phone,p_order_number:null,p_order_id:report.cases['01'].orderId};
 for(const role of ['anon','employee','service_role']){const key=role==='service_role'?config.SERVICE_ROLE_KEY:config.ANON_KEY;const token=role==='employee'?bearers.employee:key;const r=await fetch(config.API_URL+'/rest/v1/rpc/track_order_details',{method:'POST',headers:{apikey:key,authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify(args)});const data=await r.json();report.rpc??=[];report.rpc.push({role,status:r.status,data});save();check('tracking RPC ACL '+role,role==='service_role'?r.status===200:r.status===401||r.status===403,{status:r.status});}
 const bad=await http('/api/orders/track',{order_id:report.cases['01'].orderId,customer_phone:'00000000'},'anon','POST',91);check('wrong phone has no order or receipt',bad.status===404&&!bad.data.order,{response:bad});
 report.supplementCompleted=true;save();
